const input = $input.first().json;

function c(val) {
  if (val === null || val === undefined) return val;
  if (typeof val !== 'string') return val;
  return val.replace(/^"(.*)"$/s, '$1');
}

const rawText = input.output || input.text || input.response || '';

const clean = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  console.error('Analyst parse error:', e.message);
  parsed = {
    primary_drivers:     [],
    supporting_evidence: [],
    student_state:       'on_track',
  };
}

const prev = $('Prepare Analyst Input').first().json;

// Беремо score з score_breakdown.total як найнадійніше джерело
const riskScore = prev.score_breakdown?.total
  || Number(prev.risk_score_calculated)
  || 0;

return [{
  json: {
    ...prev,

    // Математично розраховані
    risk_score:               riskScore,
    risk_level:               c(prev.risk_level_calculated)         || 'low',
    urgency:                  c(prev.urgency_calculated)            || 'monitor',
    active_stages:            prev.active_stages_calculated         || [],
    days_to_dropout_estimate: c(prev.days_to_dropout)              || null,
    red_zone:                 prev.red_zone                        || false,
    score_breakdown:          prev.score_breakdown                 || {},

    // Claude пояснює
    primary_drivers:     parsed.primary_drivers              || [],
    supporting_evidence: parsed.supporting_evidence          || [],
    student_state:       c(parsed.student_state)             || 'on_track',
  }
}];

const input    = $input.first().json;
const computed = input.computed_signals || {};
const observer = input.observer_result  || {};
const hwList   = input.homework_30d     || input.homework_list || [];
const messages = input.recent_messages  || [];
const student  = input.student          || {};

const activeSignals = (observer.signals || [])
  .filter(s => s.severity >= 5)
  .map(s => '- ' + s.signal_type + ': severity ' + s.severity + ' | ' + s.details)
  .join('\n');

const hwFormatted = hwList.map(h =>
  (h.title || h.hw_id || '?') +
  ' | дедлайн: ' + (h.deadline?.split('T')[0] || '?') +
  ' | здано: ' + (h.submitted_at?.split('T')[0] || 'не здано') +
  ' | статус: ' + h.status +
  ' | оцінка: ' + (h.grade !== null && h.grade !== undefined ? h.grade : 'н/а') +
  ' | ' + (h.was_late ? 'запізно' : 'вчасно')
).join('\n');

const promptText =
  'Проаналізуй ситуацію студента і поясни причини ризику.\n\n' +
  'СТУДЕНТ: ' + (student.name || '?') + ' | ' + (student.course || '?') + '\n\n' +
  'МАТЕМАТИЧНО РОЗРАХОВАНИЙ РИЗИК:\n' +
  '- risk_score: ' + input.risk_score_calculated + '\n' +
  '- risk_level: ' + input.risk_level_calculated + '\n' +
  '- urgency: ' + input.urgency_calculated + '\n' +
  '- days_to_dropout: ' + input.days_to_dropout + '\n' +
  '- red_zone: ' + input.red_zone + '\n' +
  '- score_breakdown: base=' + input.score_breakdown.base_score +
    ' + modifiers=' + input.score_breakdown.modifiers +
    ' = ' + input.score_breakdown.total + '\n\n' +
  'АКТИВНІ СИГНАЛИ (severity >= 5):\n' +
  (activeSignals || 'немає') + '\n\n' +
  'ЧИСЛОВІ ДАНІ:\n' +
  '- Пропущено ДЗ: ' + (computed.missed_homework_count || 0) + '\n' +
  '- Запізнілих ДЗ: ' + (computed.late_homework_count || 0) + '\n' +
  '- Днів без входу: ' + (computed.last_login_days_ago == null ? 'жодного входу станом на дату' : computed.last_login_days_ago) + '\n' +
  '- Днів без повідомлень: ' + (computed.last_message_days_ago == null ? 'жодного повідомлення станом на дату' : computed.last_message_days_ago) + '\n' +
  '- submission_timing_shift: ' + (computed.submission_timing_shift || false) + '\n' +
  '- has_explicit_dropout_intent: ' + (observer.has_explicit_dropout_intent || false) + '\n\n' +
  'HOMEWORK ІСТОРІЯ:\n' +
  (hwFormatted || 'немає') + '\n\n' +
  'ОСТАННІ ПОВІДОМЛЕННЯ:\n' +
  (messages.length > 0 ? messages.join('\n') : 'немає') + '\n\n' +
  'Поверни ТІЛЬКИ валідний JSON:\n' +
  '{\n' +
  '  "primary_drivers": ["топ-3 причини людською мовою"],\n' +
  '  "supporting_evidence": ["конкретні факти з даних"],\n' +
  '  "student_state": "overwhelmed|disengaged|struggling|distracted|silent_but_ok|on_track"\n' +
  '}';

return [{
  json: {
    ...input,
    prompt_text: promptText,
  }
}];

const input    = $input.first().json;
const computed = input.computed_signals || {};
const observer = input.observer_result  || {};
const signals  = observer.signals       || [];
const hwSum    = input.hw_summary       || {};
const hwList   = input.homework_30d     || [];

// ── BASE SCORE по етапах ─────────────────────────────────────
const stageScores = {
  late_homework:        10,
  missed_live_sessions: 10,
  stopped_questions:    15,
  missed_homework:      20,
  login_gap:            15,
  negative_messages:    20,
  no_mentor_response:   25,
  missed_exam:          25,
};

const stageNumbers = {
  late_homework:        1,
  missed_live_sessions: 2,
  stopped_questions:    3,
  missed_homework:      4,
  login_gap:            5,
  negative_messages:    6,
  no_mentor_response:   7,
};

let baseScore          = 0;
const activeStages     = [];
const activeStageNames = [];

signals.forEach(signal => {
  if (signal.severity >= 5) {
    baseScore += stageScores[signal.signal_type] || 0;
    activeStageNames.push(signal.signal_type);
    const num = stageNumbers[signal.signal_type];
    if (num) activeStages.push(num);
  }
});

baseScore = Math.min(baseScore, 100);

// ── МОДИФІКАТОРИ ─────────────────────────────────────────────
let modifiers = 0;
const modifierLog = [];

const missedHw    = computed.missed_homework_count || 0;
const avgGrade    = parseFloat(hwSum.avg_grade || '100');
const dropIntent  = observer.has_explicit_dropout_intent || false;
const lastMsgDays = computed.last_message_days_ago ?? null;
const lastLogin   = computed.last_login_days_ago   ?? null;

// Dropout intent
if (dropIntent) {
  modifiers += 15;
  modifierLog.push('has_explicit_dropout_intent: +15');
}

// Submission timing shift
if (computed.submission_timing_shift === true) {
  modifiers += 10;
  modifierLog.push('submission_timing_shift: +10');
}

// Missed homework
if (missedHw >= 3) {
  modifiers += 10;
  modifierLog.push('missed_hw >= 3: +10');
} else if (missedHw >= 1) {
  modifiers += 5;
  modifierLog.push('missed_hw >= 1: +5');
}

// Avg grade
if (avgGrade < 65 && (hwSum.total || 0) > 0) {
  modifiers += 5;
  modifierLog.push('avg_grade < 65: +5');
}

// Правка 3 — пропущений іспит
const missedExam = hwList.some(h =>
  h.status === 'missed' &&
  (
    (h.title || '').toLowerCase().includes('exam') ||
    h.module >= 9
  )
);
if (missedExam) {
  modifiers += 15;
  modifierLog.push('missed_exam: +15');
}

// Правка 3 — великі запізнення
const maxLateDays = hwList
  .filter(h => h.was_late && h.submitted_at && h.deadline)
  .map(h => {
    const sub  = new Date(h.submitted_at);
    const dead = new Date(h.deadline);
    return Math.round((sub - dead) / (1000 * 60 * 60 * 24));
  })
  .reduce((max, d) => Math.max(max, d), 0);

if (maxLateDays > 30) {
  modifiers += 10;
  modifierLog.push(`max_late_days ${maxLateDays} > 30: +10`);
} else if (maxLateDays > 14) {
  modifiers += 5;
  modifierLog.push(`max_late_days ${maxLateDays} > 14: +5`);
}

// Login gap
if (lastLogin == null || lastLogin > 30) {
  modifiers += 10;
  modifierLog.push(`login_gap ${lastLogin == null ? 'нема входів станом на дату' : lastLogin} (>30): +10`);
} else if (lastLogin > 14) {
  modifiers += 5;
  modifierLog.push(`login_gap ${lastLogin} > 14: +5`);
}

// ── ОБМЕЖЕННЯ ────────────────────────────────────────────────
const onlySilent =
  activeStageNames.length === 1 &&
  activeStageNames[0] === 'stopped_questions';
if (onlySilent) {
  baseScore = Math.min(baseScore, 25);
  modifiers = 0;
}

if (missedHw === 0 && lastLogin != null && lastLogin <= 3) {
  baseScore = Math.min(baseScore, 20);
  modifiers = 0;
}

// ── ФІНАЛЬНИЙ SCORE ──────────────────────────────────────────
let riskScore = Math.min(baseScore + modifiers, 100);
riskScore     = Math.max(riskScore, 0);

// ЧЕРВОНА ЗОНА
const redZone =
  missedHw >= 3 &&
  lastMsgDays >= 10 &&
  dropIntent === true;
if (redZone) riskScore = Math.max(riskScore, 85);

// Timing shift + late homework
if (
  computed.submission_timing_shift === true &&
  activeStageNames.includes('late_homework') &&
  missedHw === 0 &&
  !dropIntent
) {
  riskScore = Math.max(riskScore, 40);
  modifierLog.push('timing_shift + late_hw → min 40');
}

// ── RISK LEVEL ───────────────────────────────────────────────
let riskLevel;
if (riskScore >= 70)      riskLevel = 'high';
else if (riskScore >= 40) riskLevel = 'medium';
else                      riskLevel = 'low';

// ── URGENCY ──────────────────────────────────────────────────
let urgency = 'monitor';

const hasStage67 = activeStageNames.some(s =>
  ['negative_messages', 'no_mentor_response'].includes(s)
);
const hasStage5  = activeStageNames.includes('login_gap');
const hasStage34 = activeStageNames.some(s =>
  ['stopped_questions', 'missed_homework'].includes(s)
);

if (hasStage67 || redZone || dropIntent) {
  urgency = 'immediate';
} else if (hasStage5 || hasStage34) {
  urgency = 'this_week';
} else if (missedExam || maxLateDays > 14) {
  urgency = 'this_week';
} else if (computed.submission_timing_shift === true) {
  urgency = 'this_week';
}

// ── DAYS TO DROPOUT ──────────────────────────────────────────
let daysToDropout;
if (signals.some(s => s.signal_type === 'no_mentor_response' && s.severity >= 7)) {
  daysToDropout = '1-5 днів';
} else if (signals.some(s => s.signal_type === 'negative_messages' && s.severity >= 7)) {
  daysToDropout = '5-7 днів';
} else if (signals.some(s => s.signal_type === 'login_gap' && s.severity >= 7)) {
  daysToDropout = '7-10 днів';
} else if (hasStage34) {
  daysToDropout = '10-14 днів';
} else if (activeStageNames.length > 0) {
  daysToDropout = '3-4 тижні';
} else {
  daysToDropout = 'немає ризику';
}

return [{
  json: {
    ...input,
    risk_score_calculated:    riskScore,
    risk_level_calculated:    riskLevel,
    urgency_calculated:       urgency,
    active_stages_calculated: activeStages,
    active_stage_names:       activeStageNames,
    days_to_dropout:          daysToDropout,
    red_zone:                 redZone,
    score_breakdown: {
      base_score:   baseScore,
      modifiers:    modifiers,
      modifier_log: modifierLog,
      total:        riskScore,
    },
  }
}];

const hwRows = $input.all().map(r => r.json);
const grades = hwRows.filter(h => h.grade !== null).map(h => h.grade);

const trigger = $('Analyst Trigger').first().json;
const data    = trigger.body || trigger;

return [{
  json: {
    student_id:       data.student_id,
    trigger:          data.trigger,
    student:          data.student,
    computed_signals: data.computed_signals,
    recent_messages:  data.recent_messages,
    observer_result:  data.observer_result,  // ← ДОДАТИ ЦЕ
    homework_30d:     hwRows,
    hw_summary: {
      total:     hwRows.length,
      graded:    hwRows.filter(h => h.status === 'graded').length,
      missed:    hwRows.filter(h => h.status === 'missed').length,
      late:      hwRows.filter(h => h.was_late === true).length,
      avg_grade: grades.length
        ? (grades.reduce((a, b) => a + b, 0) / grades.length).toFixed(1)
        : null,
    }
  }
}];
